.product-description {
  color: #666;
  line-height: 1.6;
}

.back-link {
  display: inline-block;
  margin-bottom: 1.5rem;
  color: #666;
  text-decoration: none;
  transition: color 150ms ease;
}

.back-link:hover {
  color: #111;
}

/* Skeleton container smooth entry */
.skeleton-container {
  animation: fade-in 200ms ease-out;
}

/* Skeleton loading with smooth fade transition */
.skeleton-image {
  background: #e5e5e5;
  animation: pulse 1.5s ease-in-out infinite;
}

.skeleton-text {
  height: 1rem;
  background: #e5e5e5;
  border-radius: 4px;
  margin: 0.5rem 1rem;
  animation: pulse 1.5s ease-in-out infinite;
}

.skeleton-text.short {
  width: 60%;
}

.skeleton-text.large {
  height: 2rem;
  width: 70%;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* Smooth transition from skeleton to content */
.product-info {
  animation: fade-in 300ms ease-out;
}

@keyframes fade-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Reduced motion preferences */
@media (prefers-reduced-motion: reduce) {
  /* Disable view transitions */
  @view-transition {
    navigation: none;
  }

  /* Remove all animations */
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  /* Disable page slide animations */
  ::view-transition-old(root),
  ::view-transition-new(root) {
    animation: none;
  }

  /* Disable product image shared transitions */
  ::view-transition-group(product-image-*),
  ::view-transition-old(product-image-*),
  ::view-transition-new(product-image-*) {
    animation: none;
  }

  /* Keep skeleton visible but without pulse */
  .skeleton-image,
  .skeleton-text {
    animation: none;
    opacity: 0.7;
  }

  /* Remove hover transforms */
  .product-card:hover {
    transform: none;
  }

  /* Remove content fade-in animations */
  .product-info,
  .product-grid,
  .skeleton-container,
  .product-card {
    animation: none;
  }
}
